def logical_block_coverage(blocks, start, count):
    offset = 0
    coverage = []
    for kind, length in blocks:
        end = offset + length
        if kind == 'data':
            coverage.append(max(0, min(end, start + count) - max(offset, start)))
        offset = end
    return coverage

def weighted_load(lower, upper, intervals):
    differences = [0] * (upper - lower + 1)
    for start, end, weight in intervals:
        if lower <= start < end <= upper:
            differences[start - lower] += weight
            differences[end - lower] -= weight
    loads = []
    running = 0
    for offset in range(upper - lower):
        running += differences[offset]
        loads.append(running)
    return loads

def transaction_totals(events):
    total = 0
    starts = {}
    committed = []
    for operation, transaction, amount in events:
        if operation == 'begin':
            starts[transaction] = total
        elif operation == 'add':
            total += amount
        elif operation == 'commit':
            committed.append([transaction, total - starts.pop(transaction)])
        elif operation == 'rollback':
            total = starts.pop(transaction)
    return committed

def sequence_gaps(events):
    highest = {}
    gaps = []
    for operation, key, number in events:
        if operation == 'reset':
            gaps.append(0)
        elif key not in highest:
            highest[key] = number
            gaps.append(0)
        elif number > highest[key]:
            gaps.append(number - highest[key] - 1)
            highest[key] = number
        else:
            gaps.append(0)
    return gaps

def fulfill_orders(stock, orders):
    available = list(stock)
    decisions = []
    for order in orders:
        accepted = True
        for label in order:
            if label not in available:
                accepted = False
                break
            available.remove(label)
        decisions.append(accepted)
    return decisions

def source_quorum(sources, minimum):
    votes = {}
    for source in sources:
        for label in source:
            votes[label] = votes.get(label, 0) + 1
    return sorted(label for label, count in votes.items() if count >= minimum)

def cross_source_matches(left, right):
    distinct_left = set(tuple(record) for record in left)
    distinct_right = set(tuple(record) for record in right)
    matches = 0
    for left_value, left_source in distinct_left:
        for right_value, right_source in distinct_right:
            if left_value == right_value and left_source != right_source:
                matches += 1
    return matches

def recency_evictions(capacity, updates):
    keys = []
    evicted = []
    for key, value in updates:
        if key not in keys:
            keys.append(key)
        if len(keys) > capacity:
            evicted.append(keys.pop(0))
        else:
            evicted.append(None)
    return {'evicted': evicted, 'keys': keys}

def rank_votes(sources):
    counts = {}
    first = {}
    position = 0
    for source in sources:
        for candidate, valid in source:
            if candidate not in first:
                first[candidate] = position
            if valid:
                counts[candidate] = counts.get(candidate, 0) + 1
            position += 1
    return sorted(counts, key=lambda candidate: (-counts[candidate], first[candidate]))

def quota_selection(records, quotas):
    remaining = dict(quotas)
    selected = []
    for index, record in enumerate(records):
        category = record[1]
        if remaining.get(category, 0) > 0:
            selected.append(index)
            remaining[category] -= 1
    return selected
